// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/readiness", wrapper.GetReadiness)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/dataset", wrapper.GetDataset)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/entities", wrapper.CreateEntity)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/entities/{entity_id}", wrapper.GetEntity)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/entities/{entity_id}", wrapper.PatchEntity)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/entities/{entity_id}/status", wrapper.GetAssetStatus)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/entities/{entity_id}/status", wrapper.ReportAssetStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/entities/{entity_id}/checkin", wrapper.CheckInAsset)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tasks", wrapper.ListTasks)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/tasks", wrapper.CreateTask)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/tasks/{task_id}", wrapper.GetTask)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/tasks/{task_id}/status", wrapper.UpdateTaskStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/entities/{entity_id}/tasks", wrapper.ListAssignedTasks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/queries/full", wrapper.QueryFull)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/queries/changed-since", wrapper.QueryChangedSince)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/plugins", wrapper.ListPlugins)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/plugins/{plugin_id}", wrapper.GetPlugin)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/plugins/{plugin_id}/operations", wrapper.ListPluginOperations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/plugins/{plugin_id}/operations", wrapper.SubmitPluginOperation)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/plugins/{plugin_id}/operations/{operation_id}", wrapper.GetPluginOperation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/plugins/{plugin_id}/operations/{operation_id}/cancel", wrapper.CancelPluginOperation)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/plugins/{plugin_id}/operations/{operation_id}/reports", wrapper.ReportPluginOperation)

	return m
}

